import{c as n,Q as a,j as t,m as l}from"./chunks/framework.DOi4mjdC.js";const e="/assets/%E5%BC%80%E5%8F%91Ascend-C%E7%AE%97%E5%AD%90%E7%9A%84%E5%9F%BA%E6%9C%AC%E6%B5%81%E7%A8%8B.DOd-Km0R.png",p="data:image/png;base64,",o="/assets/%E6%A0%B8%E5%87%BD%E6%95%B0%E8%B0%83%E7%94%A8%E5%85%B3%E7%B3%BB%E5%9B%BE.Cev0wVev.png",i="/assets/%E5%A4%9A%E6%A0%B8%E5%B9%B6%E8%A1%8C%E5%A4%84%E7%90%86%E7%A4%BA%E6%84%8F%E5%9B%BE.CuZCjRbI.png",c="/assets/%E5%8D%95%E6%A0%B8%E6%95%B0%E6%8D%AE%E5%88%87%E5%88%86%E7%A4%BA%E6%84%8F%E5%9B%BE.YgDzSevy.png",r="/assets/%E8%B0%83%E7%94%A8%E6%AD%A5%E9%AA%A4.Dn9gsWVd.png",v=JSON.parse('{"title":"Add自定义算子开发","description":"","frontmatter":{},"headers":[{"level":1,"title":"Add自定义算子开发","slug":"add自定义算子开发"},{"level":2,"title":"环境准备","slug":"环境准备"},{"level":2,"title":"算子分析","slug":"算子分析"},{"level":2,"title":"核函数开发","slug":"核函数开发"},{"level":2,"title":"核函数运行验证","slug":"核函数运行验证"},{"level":2,"title":"接下来的引导","slug":"接下来的引导"}],"relativePath":"guide/入门教程/快速入门/基于SIMD编程/Add自定义算子开发.md","filePath":"guide/入门教程/快速入门/基于SIMD编程/Add自定义算子开发.md"}'),u={name:"guide/入门教程/快速入门/基于SIMD编程/Add自定义算子开发.md"};function d(g,s,h,m,_,b){return a(),t("div",null,[...s[0]||(s[0]=[l('<h1 id="add自定义算子开发" tabindex="-1">Add自定义算子开发 <a class="header-anchor" href="#add自定义算子开发" aria-label="Permalink to &quot;Add自定义算子开发&quot;">​</a></h1><p>本入门教程，将会引导你完成以下任务，体验Ascend C SIMD算子开发基本流程。</p><ol><li>算子分析，明确数学表达式和计算逻辑等内容；</li><li>Add算子核函数开发；</li><li>算子核函数运行验证。</li></ol><p>在正式的开发之前，还需要先完成环境准备工作，开发Ascend C算子的基本流程如下图所示：</p><p><strong>图 1</strong> 开发Ascend C算子的基本流程<br><img src="'+e+'" alt="" title="开发Ascend-C算子的基本流程"></p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>请点击<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/01_vector/add_tpipe_tque" target="_blank" rel="noreferrer">LINK</a>获取样例代码。</li><li>使用本教程只需要您具有一定的C/C++基础，在此基础上，如果您已经对Ascend C编程模型有一定的了解，您可以在实际操作的过程中加深对理论的理解；如果您还没有开始了解Ascend C编程模型，也无需担心，您可以先尝试跑通教程中的样例，参考教程最后的<a href="#zh-cn_topic_0000001565030288_section128349412384">指引</a>进行进一步的学习。</li></ul></div><h2 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h2><ul><li><p>CANN软件安装</p><p>开发算子前，需要先准备好开发环境和运行环境，开发环境和运行环境的介绍和具体的安装步骤可参见 <a href="https://www.hiascend.com/cann/download" target="_blank" rel="noreferrer">《CANN 快速安装》</a>。</p></li><li><p>环境变量配置</p><p>安装CANN软件后，使用CANN运行用户进行编译、运行时，需要以CANN运行用户登录环境，执行source $<em>{INSTALL_DIR}</em>/set_env.sh命令设置环境变量。${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。</p></li></ul><h2 id="算子分析" tabindex="-1">算子分析 <a class="header-anchor" href="#算子分析" aria-label="Permalink to &quot;算子分析&quot;">​</a></h2><p>主要分析算子的数学表达式、输入输出的数量、Shape范围以及计算逻辑的实现，明确需要调用的Ascend C接口。下文以Add算子为例，介绍具体的分析过程。</p><ol><li><p>明确算子的数学表达式及计算逻辑。</p><p>Add算子的数学表达式为：</p><p><img src="'+p+`" alt=""></p><p>计算逻辑是：从外部存储Global Memory搬运数据至内部存储Local Memory，然后使用Ascend C计算接口完成两个输入参数相加，得到最终结果，再搬运到Global Memory上。</p></li><li><p>明确输入和输出。</p><ul><li>Add算子有两个输入：x与y，输出为z。</li><li>本样例中算子输入支持的数据类型为float，算子输出的数据类型与输入数据类型相同。</li><li>算子输入支持的shape为（8，2048），输出shape与输入shape相同。</li><li>算子输入支持的<a href="./../../../编程指南/概念原理和术语/神经网络和算子/数据排布格式.html">format</a>为：ND。</li></ul></li><li><p>确定核函数名称和参数。</p><ul><li>本样例中核函数命名为add_custom。</li><li>根据对算子输入输出的分析，确定核函数有3个参数x，y，z；x，y为输入参数，z为输出参数。</li></ul></li><li><p>确定算子实现所需接口。</p><ul><li>实现涉及外部存储和内部存储间的数据搬运，查看Ascend C API参考中的数据搬运接口，需要使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DataCopy.md" target="_blank" rel="noreferrer">DataCopy</a>来实现数据搬移。</li><li>本样例只涉及矢量计算的加法操作，查看Ascend C API参考中的矢量计算接口<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Memory%E7%9F%A2%E9%87%8F%E8%AE%A1%E7%AE%97.md" target="_blank" rel="noreferrer">Memory矢量计算</a>，初步分析可使用Add接口<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Add.md" target="_blank" rel="noreferrer">Add</a>实现x+y。</li><li>计算中使用到的Tensor数据结构，使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/AllocTensor.md" target="_blank" rel="noreferrer">AllocTensor</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/FreeTensor.md" target="_blank" rel="noreferrer">FreeTensor</a>进行申请和释放。</li><li>并行流水任务之间使用Queue队列完成同步，会使用到<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/EnQue.md" target="_blank" rel="noreferrer">EnQue</a>、<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>等接口。</li></ul></li></ol><p>通过以上分析，得到Ascend C Add算子的设计规格如下：</p><p><strong>表 1</strong> Ascend C Add算子设计规格</p><p>&lt;table&gt;&lt;tbody&gt;&lt;tr&gt;&lt;th class=&quot;firstcol&quot; valign=&quot;top&quot;&gt;&lt;p&gt;算子类型（OpType）&lt;/p&gt; &lt;/th&gt; &lt;td class=&quot;cellrowborder&quot; colspan=&quot;4&quot; valign=&quot;top&quot;&gt;&lt;p&gt;AddCustom&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;th class=&quot;firstcol&quot; rowspan=&quot;3&quot; valign=&quot;top&quot; width=&quot;19.71%&quot;&gt;&lt;p&gt;算子输入&lt;/p&gt; &lt;/th&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;19.250000000000004%&quot;&gt;&lt;p&gt;&lt;strong&gt;name&lt;/strong&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.970000000000002%&quot;&gt;&lt;p&gt;&lt;strong&gt;shape&lt;/strong&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.610000000000003%&quot;&gt;&lt;p&gt;&lt;strong&gt;data type&lt;/strong&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.460000000000004%&quot;&gt;&lt;p&gt;&lt;strong&gt;format&lt;/strong&gt;&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;x&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;(8, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;float&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;y&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;(8, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;float&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;th class=&quot;firstcol&quot; valign=&quot;top&quot; width=&quot;19.71%&quot;&gt;&lt;p&gt;算子输出&lt;/p&gt; &lt;/th&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;19.250000000000004%&quot;&gt;&lt;p&gt;z&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.970000000000002%&quot;&gt;&lt;p&gt;(8, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;21.610000000000003%&quot;&gt;&lt;p&gt;float&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;17.460000000000004%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;th class=&quot;firstcol&quot; valign=&quot;top&quot;&gt;&lt;p&gt;核函数名称&lt;/p&gt; &lt;/th&gt; &lt;td class=&quot;cellrowborder&quot; colspan=&quot;4&quot; valign=&quot;top&quot;&gt;&lt;p&gt;add_custom&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;th class=&quot;firstcol&quot; rowspan=&quot;4&quot; valign=&quot;top&quot;&gt;&lt;p&gt;使用的主要接口&lt;/p&gt; &lt;/th&gt; &lt;td class=&quot;cellrowborder&quot; colspan=&quot;4&quot; valign=&quot;top&quot;&gt;&lt;p&gt;DataCopy：数据搬运接口&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; colspan=&quot;4&quot; valign=&quot;top&quot;&gt;&lt;p&gt;Add：矢量基础算术接口&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; colspan=&quot;4&quot; valign=&quot;top&quot;&gt;&lt;p&gt;AllocTensor、FreeTensor：内存管理接口&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; colspan=&quot;4&quot; valign=&quot;top&quot;&gt;&lt;p&gt;EnQue、DeQue接口：Queue队列管理接口&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;th class=&quot;firstcol&quot; valign=&quot;top&quot;&gt;&lt;p&gt;算子实现文件名称&lt;/p&gt; &lt;/th&gt; &lt;td class=&quot;cellrowborder&quot; colspan=&quot;4&quot; valign=&quot;top&quot;&gt;&lt;p&gt;add.asc&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><h2 id="核函数开发" tabindex="-1">核函数开发 <a class="header-anchor" href="#核函数开发" aria-label="Permalink to &quot;核函数开发&quot;">​</a></h2><p>完成环境准备和初步的算子分析后，即可开始Ascend C核函数的开发。开发之前请先从<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/01_vector/add_tpipe_tque" target="_blank" rel="noreferrer">LINK</a>获取样例代码，以下样例代码在add.asc中实现。</p><p>本样例中使用多核并行计算，即把数据进行分片，分配到多个核上进行处理。Ascend C核函数是在一个核上的处理函数，所以只处理部分数据。分配方案是：假设共启用8个核，数据整体长度为8 * 2048个元素，平均分配到8个核上运行，每个核上处理的数据大小为2048个元素。对于单核上的处理数据，也可以进行数据切块，实现对数据的流水并行处理。</p><ol><li><p>根据分配方案设计一个结构体AddCustomTilingData，用于保存并行数据切分相关的参数。AddCustomTilingData定义了两个参数：totalLength、tileNum。totalLength指待处理的数据总大小为（8 * 2048）个元素，tileNum指每个核需要计算的数据块个数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct AddCustomTilingData</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    uint32_t totalLength;</span></span>
<span class="line"><span>    uint32_t tileNum;</span></span>
<span class="line"><span>};</span></span></code></pre></div></li><li><p>根据<a href="./../../../编程指南/编程模型/AI-Core-SIMD编程/核函数.html#zh-cn_topic_0000001447989210_section1915102519220">核函数定义和调用</a>中介绍的规则进行<strong>核函数的定义</strong>，并在核函数中调用算子类的Init和Process函数，算子类实现在后续步骤中介绍。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__global__ __vector__ void add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z, AddCustomTilingData tiling)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    KernelAdd op;</span></span>
<span class="line"><span>    op.Init(x, y, z, tiling.totalLength, tiling.tileNum);</span></span>
<span class="line"><span>    op.Process();</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><p>使用__global__函数类型限定符来标识它是一个核函数，可以被&lt;&lt;&lt;&gt;&gt;&gt;调用；使用__vector__函数类型限定符来标识该核函数在设备端Vector Core上执行。指针入参变量需要增加变量类型限定符__gm__，表明该指针变量指向Global Memory上某处内存地址。为了统一表达，使用GM_ADDR宏来修饰入参，GM_ADDR宏定义如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define GM_ADDR __gm__ uint8_t*</span></span></code></pre></div></li><li><p>算子类的Init函数，完成内存初始化相关工作，Process函数完成算子实现的核心逻辑。</p></li></ul></li><li><p><strong>根据矢量编程范式实现算子类</strong>，本样例中定义KernelAdd算子类，其具体成员如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class KernelAdd {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    __aicore__ inline KernelAdd(){}</span></span>
<span class="line"><span>    // 初始化函数，完成内存初始化相关操作</span></span>
<span class="line"><span>    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, uint32_t totalLength, uint32_t tileNum){}</span></span>
<span class="line"><span>    // 核心处理函数，实现算子逻辑，调用私有成员函数CopyIn、Compute、CopyOut完成矢量算子的三级流水操作</span></span>
<span class="line"><span>    __aicore__ inline void Process(){}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    // 搬入函数，从Global Memory搬运数据至Local Memory，被核心Process函数调用</span></span>
<span class="line"><span>    __aicore__ inline void CopyIn(int32_t progress){}</span></span>
<span class="line"><span>    // 计算函数，完成两个输入参数相加，得到最终结果，被核心Process函数调用</span></span>
<span class="line"><span>    __aicore__ inline void Compute(int32_t progress){}</span></span>
<span class="line"><span>    // 搬出函数，将最终结果从Local Memory搬运到Global Memory上，被核心Process函数调用</span></span>
<span class="line"><span>    __aicore__ inline void CopyOut(int32_t progress){}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    AscendC::TPipe pipe;  // TPipe内存管理对象</span></span>
<span class="line"><span>    AscendC::TQue&lt;AscendC::TPosition::VECIN, BUFFER_NUM&gt; inQueueX, inQueueY;  // 输入数据Queue队列管理对象，TPosition为VECIN</span></span>
<span class="line"><span>    AscendC::TQue&lt;AscendC::TPosition::VECOUT, BUFFER_NUM&gt; outQueueZ;  // 输出数据Queue队列管理对象，TPosition为VECOUT</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;float&gt; xGm;  // 管理输入输出Global Memory内存地址的对象，其中xGm, yGm为输入，zGm为输出</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;float&gt; yGm;</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;float&gt; zGm;</span></span>
<span class="line"><span>    uint32_t blockLength; // 每个核的计算数据长度</span></span>
<span class="line"><span>    uint32_t tileNum; // 每个核需要计算的数据块个数</span></span>
<span class="line"><span>    uint32_t tileLength; // 每个核内每个数据块的长度</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>内部函数的调用关系示意图如下：</p><p><strong>图 2</strong> 核函数调用关系图<br><img src="`+o+'" alt="" title="核函数调用关系图"></p><p>由此可见除了Init函数完成初始化外，Process中完成了对<strong>流水任务</strong>“搬入、计算、搬出”的调用，开发者可以重点关注三个流水任务的实现。</p></li><li><p>初始化函数<strong>Init</strong>主要完成以下内容：设置输入输出Global Tensor的Global Memory内存地址，通过TPipe内存管理对象为输入输出Queue分配内存。</p><p><strong>上文我们介绍到，本样例将数据切分成8块，平均分配到8个核上运行，每个核上处理的数据大小为2048个元素。那么我们是如何实现这种切分的呢？</strong></p><p>每个核上处理的数据地址需要在起始地址上增加GetBlockIdx() * blockLength（每个block处理的数据长度）的偏移来获取。这样也就实现了多核并行计算的数据切分。</p><p>以输入x为例，x + blockLength * GetBlockIdx()即为单核处理程序中x在Global Memory上的内存偏移地址，获取偏移地址后，使用GlobalTensor类的<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GlobalTensor.md" target="_blank" rel="noreferrer">SetGlobalBuffer</a>接口设定该核上Global Memory的起始地址以及长度。具体示意图如下。</p><p><strong>图 3</strong> 多核并行处理示意图<br><img src="'+i+'" alt="" title="多核并行处理示意图"></p><p><strong>上面已经实现了多核数据的切分，那么单核上的处理数据如何进行切分？</strong></p><p>对于单核上的处理数据，可以进行数据切块（Tiling），在本示例中，仅作为参考，将数据切分成8块（并不意味着8块就是性能最优）。切分后的每个数据块再次切分成2块，即可开启<a href="./../../../编程指南/概念原理和术语/性能优化技术原理/DoubleBuffer.html">double buffer</a>，实现流水线之间的并行。</p><p>这样单核上的数据（2048个数）被切分成16块，每块tileLength（128）个数据。TPipe为inQueueX分配了两块大小为tileLength * sizeof(float)个字节的内存块，每个内存块能容纳tileLength（128）个float类型数据。数据切分示意图如下。</p><p><strong>图 4</strong> 单核数据切分示意图<br><img src="'+c+`" alt="" title="单核数据切分示意图"></p><p>具体的初始化函数代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Kernel侧所需头文件</span></span>
<span class="line"><span>#include &quot;kernel_operator.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>constexpr int32_t BUFFER_NUM = 2;                                     // tensor num for each queue</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, uint32_t totalLength, uint32_t tileNum)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>     this-&gt;blockLength = totalLength / AscendC::GetBlockNum();     // length computed of each core</span></span>
<span class="line"><span>     this-&gt;tileNum = tileNum;                                      // split data into 8 tiles for each core</span></span>
<span class="line"><span>     this-&gt;tileLength = this-&gt;blockLength / tileNum / BUFFER_NUM;  // separate to 2 parts, due to double buffer</span></span>
<span class="line"><span>     // get start index for current core, core parallel</span></span>
<span class="line"><span>     xGm.SetGlobalBuffer((__gm__ float *)x + this-&gt;blockLength * AscendC::GetBlockIdx(), this-&gt;blockLength);</span></span>
<span class="line"><span>     yGm.SetGlobalBuffer((__gm__ float *)y + this-&gt;blockLength * AscendC::GetBlockIdx(), this-&gt;blockLength);</span></span>
<span class="line"><span>     zGm.SetGlobalBuffer((__gm__ float *)z + this-&gt;blockLength * AscendC::GetBlockIdx(), this-&gt;blockLength);</span></span>
<span class="line"><span>     // pipe alloc memory to queue, the unit is Bytes</span></span>
<span class="line"><span>     pipe.InitBuffer(inQueueX, BUFFER_NUM, this-&gt;tileLength * sizeof(float));</span></span>
<span class="line"><span>     pipe.InitBuffer(inQueueY, BUFFER_NUM, this-&gt;tileLength * sizeof(float));</span></span>
<span class="line"><span>     pipe.InitBuffer(outQueueZ, BUFFER_NUM, this-&gt;tileLength * sizeof(float));</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>基于矢量编程范式，将核函数的实现分为3个基本任务：CopyIn，Compute，CopyOut。<strong>Process</strong>函数中通过如下方式调用这三个函数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void Process()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // loop count need to be doubled, due to double buffer</span></span>
<span class="line"><span>    int32_t loopCount = this-&gt;tileNum * BUFFER_NUM;</span></span>
<span class="line"><span>    // tiling strategy, pipeline parallel</span></span>
<span class="line"><span>    for (int32_t i = 0; i &lt; loopCount; i++) {</span></span>
<span class="line"><span>        CopyIn(i);</span></span>
<span class="line"><span>        Compute(i);</span></span>
<span class="line"><span>        CopyOut(i);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ol><li><p>CopyIn函数实现。</p><ol><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DataCopy.md" target="_blank" rel="noreferrer">DataCopy</a>接口将GlobalTensor数据拷贝到LocalTensor。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/EnQue.md" target="_blank" rel="noreferrer">EnQue</a>将LocalTensor放入VecIn的Queue中。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void CopyIn( int32_t progress)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // alloc tensor from queue memory</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; xLocal = inQueueX.AllocTensor&lt;float&gt;();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; yLocal = inQueueY.AllocTensor&lt;float&gt;();</span></span>
<span class="line"><span>    // copy progress_th tile from global tensor to local tensor</span></span>
<span class="line"><span>    AscendC::DataCopy(xLocal, xGm[progress * this-&gt;tileLength], this-&gt;tileLength);</span></span>
<span class="line"><span>    AscendC::DataCopy(yLocal, yGm[progress * this-&gt;tileLength], this-&gt;tileLength);</span></span>
<span class="line"><span>    // enque input tensors to VECIN queue</span></span>
<span class="line"><span>    inQueueX.EnQue(xLocal);</span></span>
<span class="line"><span>    inQueueY.EnQue(yLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Compute函数实现。</p><ol><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>从VecIn中取出LocalTensor。</li><li>使用Ascend C接口<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Add.md" target="_blank" rel="noreferrer">Add</a>完成矢量计算。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/EnQue.md" target="_blank" rel="noreferrer">EnQue</a>将计算结果LocalTensor放入到VecOut的Queue中。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/FreeTensor.md" target="_blank" rel="noreferrer">FreeTensor</a>将释放不再使用的LocalTensor。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void Compute(int32_t progress)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // deque input tensors from VECIN queue</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; xLocal = inQueueX.DeQue&lt;float&gt;();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; yLocal = inQueueY.DeQue&lt;float&gt;();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; zLocal = outQueueZ.AllocTensor&lt;float&gt;();</span></span>
<span class="line"><span>    // call Add instr for computation</span></span>
<span class="line"><span>    AscendC::Add(zLocal, xLocal, yLocal, this-&gt;tileLength);</span></span>
<span class="line"><span>    // enque the output tensor to VECOUT queue</span></span>
<span class="line"><span>    outQueueZ.EnQue&lt;float&gt;(zLocal);</span></span>
<span class="line"><span>    // free input tensors for reuse</span></span>
<span class="line"><span>    inQueueX.FreeTensor(xLocal);</span></span>
<span class="line"><span>    inQueueY.FreeTensor(yLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>CopyOut函数实现。</p><ol><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>接口从VecOut的Queue中取出LocalTensor。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DataCopy.md" target="_blank" rel="noreferrer">DataCopy</a>接口将LocalTensor拷贝到GlobalTensor上。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/FreeTensor.md" target="_blank" rel="noreferrer">FreeTensor</a>将不再使用的LocalTensor进行回收。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> __aicore__ inline void CopyOut(int32_t progress)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // deque output tensor from VECOUT queue</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; zLocal = outQueueZ.DeQue&lt;float&gt;();</span></span>
<span class="line"><span>    // copy progress_th tile from local tensor to global tensor</span></span>
<span class="line"><span>    AscendC::DataCopy(zGm[progress * this-&gt;tileLength], zLocal, this-&gt;tileLength);</span></span>
<span class="line"><span>    // free output tensor for reuse</span></span>
<span class="line"><span>    outQueueZ.FreeTensor(zLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div></li></ol></li></ol><h2 id="核函数运行验证" tabindex="-1">核函数运行验证 <a class="header-anchor" href="#核函数运行验证" aria-label="Permalink to &quot;核函数运行验证&quot;">​</a></h2><p>完成Kernel侧核函数开发后，即可编写Host侧的核函数调用程序。实现从Host侧的APP程序调用算子，执行计算过程。</p><ol><li><p>Host侧应用程序框架的编写。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Host侧应用程序需要包含的头文件</span></span>
<span class="line"><span>#include &quot;acl/acl.h&quot;</span></span>
<span class="line"><span>// Kernel侧需要包含的头文件</span></span>
<span class="line"><span>#include &quot;kernel_operator.h&quot;</span></span>
<span class="line"><span>// 核函数开发部分</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__global__ __vector__ void add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z, AddCustomTilingData tiling)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    KernelAdd op;</span></span>
<span class="line"><span>    op.Init(x, y, z, tiling.totalLength, tiling.tileNum);</span></span>
<span class="line"><span>    op.Process();</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 通过&lt;&lt;&lt;...&gt;&gt;&gt;内核调用符调用算子</span></span>
<span class="line"><span>add_custom&lt;&lt;&lt;numBlocks, nullptr, stream&gt;&gt;&gt;(xDevice, yDevice, zDevice, tiling);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 算子验证主程序</span></span>
<span class="line"><span>int32_t main(int32_t argc, char* argv[])</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    uint32_t numBlocks = 8;</span></span>
<span class="line"><span>    constexpr uint32_t totalLength = 8 * 2048;</span></span>
<span class="line"><span>    size_t inputByteSize = totalLength * sizeof(float);</span></span>
<span class="line"><span>    size_t outputByteSize = totalLength * sizeof(float);</span></span>
<span class="line"><span>    AddCustomTilingData tiling = {totalLength, 8};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    add_custom&lt;&lt;&lt;numBlocks, nullptr, stream&gt;&gt;&gt;(xDevice, yDevice, zDevice, tiling);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>编写<strong>通过&lt;&lt;&lt;...&gt;&gt;&gt;内核调用符调用</strong>算子的代码。</p><p><strong>图 5</strong> 调用步骤<br><img src="`+r+`" alt="" title="调用步骤"></p><p>如下示例中的acl API使用方法请参考<a href="https://hiascend.com/document/redirect/CannCommunityRuntimeApi" target="_blank" rel="noreferrer">《Runtime运行时API》</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    uint8_t* xHost = nullptr;</span></span>
<span class="line"><span>    uint8_t* yHost = nullptr;</span></span>
<span class="line"><span>    uint8_t* zHost = nullptr;</span></span>
<span class="line"><span>    uint8_t* xDevice = nullptr;</span></span>
<span class="line"><span>    uint8_t* yDevice = nullptr;</span></span>
<span class="line"><span>    uint8_t* zDevice = nullptr;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    aclInit(nullptr);</span></span>
<span class="line"><span>    int32_t deviceId = 0;</span></span>
<span class="line"><span>    aclrtSetDevice(deviceId);</span></span>
<span class="line"><span>    aclrtStream stream = nullptr;</span></span>
<span class="line"><span>    aclrtCreateStream(&amp;stream);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    aclrtMallocHost((void**)(&amp;xHost), inputByteSize);</span></span>
<span class="line"><span>    aclrtMallocHost((void**)(&amp;yHost), inputByteSize);</span></span>
<span class="line"><span>    aclrtMallocHost((void**)(&amp;zHost), outputByteSize);</span></span>
<span class="line"><span>    aclrtMalloc((void**)&amp;xDevice, inputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);</span></span>
<span class="line"><span>    aclrtMalloc((void**)&amp;yDevice, inputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);</span></span>
<span class="line"><span>    aclrtMalloc((void**)&amp;zDevice, outputByteSize, ACL_MEM_MALLOC_HUGE_FIRST);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ReadFile(&quot;./input/input_x.bin&quot;, inputByteSize, xHost, inputByteSize);</span></span>
<span class="line"><span>    ReadFile(&quot;./input/input_y.bin&quot;, inputByteSize, yHost, inputByteSize);</span></span>
<span class="line"><span>    aclrtMemcpy(xDevice, inputByteSize, xHost, inputByteSize, ACL_MEMCPY_HOST_TO_DEVICE);</span></span>
<span class="line"><span>    aclrtMemcpy(yDevice, inputByteSize, yHost, inputByteSize, ACL_MEMCPY_HOST_TO_DEVICE);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    add_custom&lt;&lt;&lt;numBlocks, nullptr, stream&gt;&gt;&gt;(xDevice, yDevice, zDevice, tiling);</span></span>
<span class="line"><span>    aclrtSynchronizeStream(stream);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    aclrtMemcpy(zHost, outputByteSize, zDevice, outputByteSize, ACL_MEMCPY_DEVICE_TO_HOST);</span></span>
<span class="line"><span>    WriteFile(&quot;./output/output.bin&quot;, zHost, outputByteSize);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    aclrtFree(xDevice);</span></span>
<span class="line"><span>    aclrtFree(yDevice);</span></span>
<span class="line"><span>    aclrtFree(zDevice);</span></span>
<span class="line"><span>    aclrtFreeHost(xHost);</span></span>
<span class="line"><span>    aclrtFreeHost(yHost);</span></span>
<span class="line"><span>    aclrtFreeHost(zHost);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    aclrtDestroyStream(stream);</span></span>
<span class="line"><span>    aclrtResetDevice(deviceId);</span></span>
<span class="line"><span>    aclFinalize();</span></span></code></pre></div></li><li><p>CMake编译配置如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmake_minimum_required(VERSION 3.16)</span></span>
<span class="line"><span># CMAKE_ASC_ARCHITECTURES是用来决定NPU架构的编译参数，可选值为：dav-2201, dav-3510</span></span>
<span class="line"><span>set(CMAKE_ASC_ARCHITECTURES &quot;dav-2201&quot; CACHE STRING &quot;NPU architecture: dav-2201, dav-3510&quot;)</span></span>
<span class="line"><span># find_package(ASC)是CMake中用于查找和配置Ascend C编译工具链的命令</span></span>
<span class="line"><span>find_package(ASC REQUIRED)</span></span>
<span class="line"><span># 指定项目支持的语言包括ASC和CXX，ASC表示支持使用毕昇编译器对Ascend C编程语言进行编译</span></span>
<span class="line"><span>project(kernel_samples LANGUAGES ASC CXX)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>add_executable(add</span></span>
<span class="line"><span>    add.asc</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 通过编译选项设置NPU架构</span></span>
<span class="line"><span>target_compile_options(add PRIVATE</span></span>
<span class="line"><span>    $&lt;$&lt;COMPILE_LANGUAGE:ASC&gt;:--npu-arch=\${CMAKE_ASC_ARCHITECTURES}&gt;</span></span>
<span class="line"><span>)</span></span></code></pre></div></li><li><p>编译和运行步骤如下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p build &amp;&amp; cd build;</span></span>
<span class="line"><span>cmake -DCMAKE_ASC_ARCHITECTURES=dav-2201 ..;make -j;</span></span>
<span class="line"><span>python3 ../scripts/gen_data.py</span></span>
<span class="line"><span>./demo</span></span>
<span class="line"><span>python3 ../scripts/verify_result.py output/output.bin output/golden.bin</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>该样例仅支持如下型号： <ul><li>Ascend 950PR/Ascend 950DT</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></li><li><em>-</em>-npu-arch用于指定NPU的架构版本，dav-后为架构版本号，请通过CMAKE_ASC_ARCHITECTURES传入您实际使用的架构版本号。各AI处理器型号对应的架构版本号请通过<a href="./../../../编程指南/语言扩展层/SIMD-BuiltIn关键字.html#table65291052154114">AI处理器型号和__NPU_ARCH__的对应关系</a>进行查询。</li></ul></div></li></ol><h2 id="接下来的引导" tabindex="-1">接下来的引导 <a class="header-anchor" href="#接下来的引导" aria-label="Permalink to &quot;接下来的引导&quot;">​</a></h2><p>如果您对教程中的多核并行、流水编程等概念不了解，导致阅读过程有些吃力，可以参考<a href="./../../../编程指南/编程模型/编程模型.html">编程模型</a>学习基本概念，再来回顾本教程；如果您已经了解相关概念，并跑通了该样例，您可以参考<a href="./../../../算子实践参考/SIMD算子实现/矢量编程/矢量编程.html">矢量编程</a>了解Ascend C矢量编程中的更多细节。</p>`,23)])])}const C=n(u,[["render",d]]);export{v as __pageData,C as default};
